      case 'development':
      case 'in_dev':
        return { next: 'pr', detail: 'dev leg running', blocking: false };
      case 'queued':
        return { next: 'dev', detail: null, blocking: false };
      case 'inbox':
        return { next: 'triage', detail: null, blocking: false };
