      if (e.at == null) return null;
      var next = entries[i + 1];
      if (next && next.at != null) return Math.max(0, next.at - e.at);
      if (next) return null;                        // next has no stamp yet
      return terminal ? null : Math.max(0, nowMs - e.at);
