          ? { next: 'rework', detail: 'CI red', blocking: true }
          : { next: 'validation', detail: null, blocking: false };
      case 'pr_validation':
        return red
          ? { next: 'rework', detail: 'CI red', blocking: true }
          : { next: 'review', detail: 'CI running', blocking: false };
