    var s = flow.ciSplit({ checks: { verdict: 'in_progress', at: '2026-10-03T12:00:00Z',
      runStartedAt: '2026-10-03T11:59:00Z' } }, iso('2026-10-03T12:10:00Z'));
    assert.equal(s.queueMs, 0);
  });
});

