  { state: 'review',      at: iso('2026-10-03T11:00:00Z') },
  { state: 'pr_created', at: iso('2026-10-03T11:30:00Z') },
  { state: 'review',      at: iso('2026-10-03T11:45:00Z') },
  { state: 'approved_queue', at: iso('2026-10-03T12:00:00Z') }
];
