                devStartedAtByIssue[it.number] = prevCard.devStartedAt;
            } else if (hasPrev) {
                devStartedAtByIssue[it.number] = now;
            }
        }
        issueHistory[it.number] = nextHistory(
            prevCard, pix.issueState[it.number], bucket, now, hasPrev);
        if (inDev) {
